import styles from './styles.scss';

/* ------------------------------------------------------------------ *
 * x-soori-library-activity-timeline
 * A chronological activity / audit feed: a titled card over a list of rows,
 * each row = clock icon + timestamp (fixed column) + actor + description.
 * An entry can carry an optional `status` that highlights the row (e.g. a
 * "Policy bound" success row: green left accent + faint tint + green text).
 *
 * COMPOSITION (per rules §0/§2): the clock glyph is a STANDARD <now-icon>
 * (declared in now-ui.json innerComponents; the instance supplies the Horizon
 * version — NOT bundled, §3.1 [[do-not-bundle-now-star-use-horizon]]).
 *
 * OWNED markup (documented §3 exception): the card shell, the "Activity" header,
 * and the row grid (timestamp column + actor + description) have no default DS
 * equivalent — no now-* component renders a time·actor·description audit feed
 * (progress-list is a progress widget, wrong semantics). The container is a PLAIN
 * <div>, NOT now-card, so we own its padding/border/radius exactly (matching the
 * Handoff node 3120-14261) and it can be re-styled from the UIB Styles tab — the
 * same approach used for configurable-label-value's stacked cards; now-card injects
 * its own slot padding that stacks on top of ours. All themed with hardcoded
 * near-neutral hex where the neutral/surface tokens resolve near-white on the
 * instance [[data-table-row-border-hardcode-grey]], [[now-color-neutral-scale-resolves-light]].
 *
 * INPUT: a single bound `entries` JSON array (object-wrapped default — a top-level
 * array JSON default breaks the prod build [[now-ui-json-array-default-gotcha]]):
 * { entries: [ { timestamp, actor, description, icon?, status?, id? } ] }
