		const s = v.trim();
		if (!s) return [];
		try { v = JSON.parse(s); } catch (e) { return []; }
	}
	if (Array.isArray(v)) return v;
	if (v && typeof v === 'object' && Array.isArray(v.entries)) return v.entries;
	return [];
};

/* Built-in status keys → CSS modifier. Anything else (or missing) → plain row,
 * UNLESS the consumer supplies a custom colour for that key via `statusColors`
 * (then the row is coloured inline from that map — see rowStatus / statusStyle). */
const STATUSES = ['success', 'info', 'warning', 'critical'];
const builtinStatus = (s) => {
	const k = String(s || '').toLowerCase().trim();
	return STATUSES.indexOf(k) >= 0 ? k : '';
};

