const parseJson = (raw) => {
	if (raw == null) return null;
	if (typeof raw === 'string') {
		const s = raw.trim();
		if (!s) return null;
		try { return JSON.parse(s); } catch (e) { return null; }
	}
	return typeof raw === 'object' ? raw : null;
};

