 * mapped name and the canonical default (so a record shaped {date,user,text} works
 * via field mapping, and the documented {timestamp,actor,description} works as-is). */
const fieldOf = (entry, mapped, fallback) => {
	if (!entry || typeof entry !== 'object') return '';
	if (mapped && entry[mapped] != null) return entry[mapped];
	if (entry[fallback] != null) return entry[fallback];
	return '';
};

const view = (state) => {
