	const entries = asEntries(p.entries);
	const title = p.title;
	const defaultIcon = p.defaultIcon || 'clock-outline';

	/* Field mapping — bind to ANY record shape without pre-transforming the data.
	 * Each *Field prop names the column to read; empty falls back to the canonical
	 * key (timestamp/actor/description/status/icon). */
	const fTime = p.timestampField;
	const fActor = p.actorField;
	const fDesc = p.descriptionField;
	const fStatus = p.statusField;
	const fIcon = p.iconField;

	/* Optional consumer-defined status → colour map, e.g.
	 * { "bound": "#1f9d57", "lapsed": "#d92d20" }. A matched key colours the row's
	 * left accent + text inline (built-in success/info/warning/critical still work
	 * via CSS even without a map entry). */
	const statusColors = parseJson(p.statusColors) || {};

	/* Fixed timestamp-column width (px or any CSS length). */
	const timeWidth = str(p.timeColumnWidth) || '154px';
	const showIcon = p.showIcon !== false && p.showIcon !== 'false';

	return (
		<div className="at-card">
			{title ? <div className="at-header">{title}</div> : null}

			{entries.length ? (
				<div className="at-body" role="list">
					{entries.map((e, i) => {
						const statusVal = str(fieldOf(e, fStatus, 'status'));
						const builtin = builtinStatus(statusVal);
						const customColor = statusColors[statusVal] || statusColors[statusVal.toLowerCase()];
						const rowCls =
