						const rowStyle = customColor
							? { borderLeftColor: customColor, background: 'transparent' }
							: null;
						const detailStyle = customColor ? { color: customColor } : null;
						const icon = str(fieldOf(e, fIcon, 'icon')) || defaultIcon;
						return (
