									) : null}
									<span className="at-time-text" style={detailStyle}>{str(fieldOf(e, fTime, 'timestamp'))}</span>
								</div>
								<div className="at-detail">
									{fieldOf(e, fActor, 'actor') ? (
										<span className="at-actor" style={detailStyle}>{str(fieldOf(e, fActor, 'actor'))}</span>
									) : null}
									<span className="at-desc" style={detailStyle}>{str(fieldOf(e, fDesc, 'description'))}</span>
