	properties: {
		title: { default: '' },
		entries: { default: { entries: [] } },
		defaultIcon: { default: '' },
		showIcon: { default: true },
		timeColumnWidth: { default: '' },
		timestampField: { default: '' },
		actorField: { default: '' },
		descriptionField: { default: '' },
		statusField: { default: '' },
		iconField: { default: '' },
		statusColors: { default: {} },
		emptyMessage: { default: '' },
	},
});
